/* Logic used by the Cashfree workflow's Code nodes. Kept here so it can be tested
   outside n8n; the workflow file embeds the same functions. */
// n8n's Code nodes run in a sandbox with require() turned off, so the signature check
// carries its own SHA-256 rather than Node's crypto module.
const K256 = [
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];

// Bytes, not characters: a rupee sign in the body is three bytes and must be hashed as three.
function utf8Bytes(str) {
  const s = String(str), out = [];
  for (let i = 0; i < s.length; i++) {
    let c = s.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdbff && i + 1 < s.length) {
      const lo = s.charCodeAt(i + 1);
      if (lo >= 0xdc00 && lo <= 0xdfff) { c = 0x10000 + ((c - 0xd800) << 10) + (lo - 0xdc00); i++; }
    }
    if (c < 0x80) out.push(c);
    else if (c < 0x800) out.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else out.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  return out;
}

function sha256(bytes) {
  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const msg = bytes.slice(), bitLen = bytes.length * 8;
  msg.push(0x80);
  while (msg.length % 64 !== 56) msg.push(0);
  // length goes in as 64 bits; the high word stays 0 for anything a webhook could send
  msg.push(0, 0, 0, 0, (bitLen >>> 24) & 0xff, (bitLen >>> 16) & 0xff, (bitLen >>> 8) & 0xff, bitLen & 0xff);

  const w = new Array(64);
  const rotr = (x, n) => ((x >>> n) | (x << (32 - n))) >>> 0;

  for (let i = 0; i < msg.length; i += 64) {
    for (let t = 0; t < 16; t++) {
      w[t] = ((msg[i + t * 4] << 24) | (msg[i + t * 4 + 1] << 16) | (msg[i + t * 4 + 2] << 8) | msg[i + t * 4 + 3]) >>> 0;
    }
    for (let t = 16; t < 64; t++) {
      const s0 = (rotr(w[t - 15], 7) ^ rotr(w[t - 15], 18) ^ (w[t - 15] >>> 3)) >>> 0;
      const s1 = (rotr(w[t - 2], 17) ^ rotr(w[t - 2], 19) ^ (w[t - 2] >>> 10)) >>> 0;
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let t = 0; t < 64; t++) {
      const S1 = (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) >>> 0;
      const ch = ((e & f) ^ (~e & g)) >>> 0;
      const t1 = (h + S1 + ch + K256[t] + w[t]) >>> 0;
      const S0 = (rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) >>> 0;
      const maj = ((a & b) ^ (a & c) ^ (b & c)) >>> 0;
      const t2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0;
      d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    H[0] = (H[0] + a) >>> 0; H[1] = (H[1] + b) >>> 0; H[2] = (H[2] + c) >>> 0; H[3] = (H[3] + d) >>> 0;
    H[4] = (H[4] + e) >>> 0; H[5] = (H[5] + f) >>> 0; H[6] = (H[6] + g) >>> 0; H[7] = (H[7] + h) >>> 0;
  }
  const out = [];
  for (const v of H) out.push((v >>> 24) & 0xff, (v >>> 16) & 0xff, (v >>> 8) & 0xff, v & 0xff);
  return out;
}

function base64(bytes) {
  const A = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  let out = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const n = (bytes[i] << 16) | ((bytes[i + 1] || 0) << 8) | (bytes[i + 2] || 0);
    out += A[(n >> 18) & 63] + A[(n >> 12) & 63];
    out += i + 1 < bytes.length ? A[(n >> 6) & 63] : '=';
    out += i + 2 < bytes.length ? A[n & 63] : '=';
  }
  return out;
}

// The raw body can arrive base64-encoded as binary, and the sandbox has no Buffer,
// so it is decoded here. The signature is over these exact bytes.
function base64ToUtf8(b64) {
  const A = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  const s = String(b64).replace(/[^A-Za-z0-9+/]/g, ''), bytes = [];
  for (let i = 0; i < s.length; i += 4) {
    const n = (A.indexOf(s[i]) << 18) | (A.indexOf(s[i + 1]) << 12) |
              ((A.indexOf(s[i + 2]) & 63) << 6) | (A.indexOf(s[i + 3]) & 63);
    bytes.push((n >> 16) & 0xff);
    if (i + 2 < s.length) bytes.push((n >> 8) & 0xff);
    if (i + 3 < s.length) bytes.push(n & 0xff);
  }
  let out = '';
  for (let i = 0; i < bytes.length; i++) {
    const c = bytes[i];
    if (c < 0x80) out += String.fromCharCode(c);
    else if (c < 0xe0) { out += String.fromCharCode(((c & 31) << 6) | (bytes[++i] & 63)); }
    else if (c < 0xf0) { out += String.fromCharCode(((c & 15) << 12) | ((bytes[++i] & 63) << 6) | (bytes[++i] & 63)); }
    else {
      const cp = ((c & 7) << 18) | ((bytes[++i] & 63) << 12) | ((bytes[++i] & 63) << 6) | (bytes[++i] & 63);
      const u = cp - 0x10000;
      out += String.fromCharCode(0xd800 + (u >> 10), 0xdc00 + (u & 1023));
    }
  }
  return out;
}

function hmacSha256Base64(key, message) {
  let k = utf8Bytes(key);
  if (k.length > 64) k = sha256(k);
  while (k.length < 64) k.push(0);
  const inner = [], outer = [];
  for (let i = 0; i < 64; i++) { inner.push(k[i] ^ 0x36); outer.push(k[i] ^ 0x5c); }
  return base64(sha256(outer.concat(sha256(inner.concat(utf8Bytes(message))))));
}

// Compares in time that does not depend on where the first difference is, so a forger
// cannot learn the signature one character at a time.
function sameSecret(a, b) {
  const x = String(a), y = String(b);
  let diff = x.length ^ y.length;
  for (let i = 0; i < Math.max(x.length, y.length); i++) {
    diff |= (x.charCodeAt(i) || 0) ^ (y.charCodeAt(i) || 0);
  }
  return diff === 0;
}

// What we are willing to charge. The browser sends an amount, but we never trust it:
// we price from this table, or from the book for a monthly bill.
const PRODUCTS = [
  { id: 'std', name: 'WD Standard',   price: 999,  months: 1 },
  { id: 'pro', name: 'WD Pro',        price: 1800, months: 1 },
  { id: 'exc', name: 'WD Exclusive',  price: 2500, months: 1 },
  { id: 'res', name: 'WD Reserve',    price: 5555, months: 1 },
  { id: 'legacy', name: 'Legacy',     price: 500,  months: 1 },
  { id: 'wash', name: 'WD Wash', price: 199, months: 0 },
  { id: 'deep', name: 'WD Deep Cleaning', price: 800, months: 0 },
];

// Both pages send the product name inside `label` ("WD Pro", "WD Pro · Scorpio N").
// Longest name first so "Pro wash" never matches before "WD Pro" on the wrong string.
function findProduct(body) {
  if (body.planId) {
    const byId = PRODUCTS.find(p => p.id === body.planId);
    if (byId) return byId;
  }
  const label = String(body.label || '').trim();
  const byName = PRODUCTS.slice().sort((a, b) => b.name.length - a.name.length)
    .find(p => label.toLowerCase().startsWith(p.name.toLowerCase()));
  return byName || null;
}

const isBill = body => /bill/i.test(String(body.kind || ''));

// Returns {amount, months, label} or {error}. `owed` is what the book says, for a bill.
function priceOrder(body, owed) {
  const asked = Number(body.amount);
  if (!Number.isFinite(asked) || asked < 1 || asked > 50000) return { error: "That amount doesn't look right." };

  if (isBill(body)) {
    if (!owed || !Number.isFinite(owed.due) || owed.due < 1) return { error: "We couldn't find a bill for that car." };
    const months = owed.fee > 0 ? Math.max(1, Math.floor(owed.due / owed.fee)) : 1;
    return { amount: Math.round(owed.due), months, label: body.label || 'Monthly bill' };
  }
  const p = findProduct(body);
  if (!p) return { error: "We couldn't work out what you're paying for." };
  if (Math.round(asked) !== p.price) return { error: 'That price is out of date. Reload the page and try again.' };
  return { amount: p.price, months: p.months, label: p.name };
}

// Cashfree signs (timestamp + raw body) with the secret key, base64 of HMAC-SHA256.
function verifyWebhook(rawBody, timestamp, signature, secret, nowMs) {
  if (!rawBody || !timestamp || !signature || !secret) return { ok: false, why: 'missing signature' };
  const expected = hmacSha256Base64(secret, timestamp + rawBody);
  if (!sameSecret(expected, signature)) return { ok: false, why: 'bad signature' };
  const tsMs = Number(timestamp) > 1e12 ? Number(timestamp) : Number(timestamp) * 1000;
  const age = (nowMs - tsMs) / 1000;
  if (!Number.isFinite(age) || Math.abs(age) > 300) return { ok: false, why: 'too old' };
  return { ok: true };
}

// n8n hands back Notion dates as {start: "2026-10-29"}, not a string. Reading it as a
// string silently makes every car look unpaid, so always come through here.
function dateText(v) {
  if (!v) return '';
  if (typeof v === 'string') return v.slice(0, 10);
  if (typeof v === 'object' && v.start) return String(v.start).slice(0, 10);
  return '';
}

// A new cycle runs from the later of today and the current paid-up date, never from today
// alone, or a late payer quietly loses the weeks they already paid for.
function advancePaidUpTo(paidUpTo, months, todayISO) {
  const cur = dateText(paidUpTo), from = cur && cur > todayISO ? cur : todayISO;
  const d = new Date(from + 'T00:00:00Z');
  const origDay = d.getUTCDate();
  d.setUTCMonth(d.getUTCMonth() + months);
  // Clamp month-end overflow: Jan 31 + 1 month must be Feb 28, not Mar 3
  if (d.getUTCDate() !== origDay) d.setUTCDate(0);
  return d.toISOString().slice(0, 10);
}

// The customer app asks "what does DL9436 owe?". We answer with minimal payment info only.
// P6/P5: require the full normalised plate; exact match; return only what the payment screen needs.
const res = $input.first().json;
const asked = ($('Bill poochho (webhook)').first().json.query.car || '').toString();
const key = asked.replace(/[^A-Za-z0-9]/g, '').toUpperCase();
if (key.length < 6) return [{ json: { found: false } }]; // too short to be a real plate

const rows = (res.results || []).filter(r => {
  const num = (r.properties['Car Number']?.rich_text || []).map(t => t.plain_text).join('');
  return num.replace(/[^A-Za-z0-9]/g, '').toUpperCase() === key; // exact match
});
if (!rows.length) return [{ json: { found: false } }];

const r = rows[0], p = r.properties;
const fee = p['Monthly Fee']?.number || 0;
const owes = p['Owes Now']?.number || 0;
// Return only what the payment screen needs: no plate, no address, no pageId
return [{ json: {
  found: true,
  fee, owes, due: owes > 0 ? owes : fee,
  paidTo: dateText(p['Service Paid Up To']?.date),
  status: p['Account Status']?.select?.name || 'Unknown',
} }];

// ---------------------------------------------------------------------------
// Order pricing needs no secret here: Cashfree keys live in the "Cashfree live" credential.
// (The webhook secret is the env var CASHFREE_SECRET, read only by "Sach mein Cashfree hai?".)
// Sandbox while testing. Change to false the day you go live, together with
// CF_MODE in pay/index.html and PAY_LIVE in the customer app.
const SANDBOX = false;
// ---------------------------------------------------------------------------
